package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var a, b, c, l int
	fmt.Fscan(reader, &a, &b, &c, &l)

	// Sort the sticks
	if a > b {
		a, b = b, a
	}
	if b > c {
		b, c = c, b
	}
	if a > b {
		a, b = b, a
	}

	total := 0
	// Iterate over all possible increments for the largest stick
	for x := 0; x <= l; x++ {
		// The remaining increments to distribute among the other two sticks
		rem := l - x
		// The maximum possible value for the sum of the other two sticks
		maxSum := a + b + rem
		// The minimum required value for the sum of the other two sticks
		minSum := c + x + 1
		if maxSum >= minSum {
			// The number of ways to distribute the remaining increments
			// such that the sum of the other two sticks is at least minSum
			// and at most maxSum
			ways := (maxSum - minSum + 1) * (rem + 1)
			// Subtract the cases where the sum is less than minSum
			if minSum > a+b {
				// The number of ways where the sum is less than minSum
				invalid := (minSum - (a + b)) * (rem + 1)
				ways -= invalid
			}
			total += ways
		}
	}

	fmt.Println(total)
}
