	// Let's compute this.

	k := c - a - b
	if k < 0 {
		// All ways are valid
		total = (l + 1) * (l + 2) * (l + 3) / 6
		fmt.Println(total)
		return
	}

	// Compute total ways
	total = (l + 1) * (l + 2) * (l + 3) / 6

	// Compute invalid ways
	invalid := 0
	for s := 0; s <= l; s++ {
		m := (s + k) / 2
		if m >= s {
			// All ways for this s are invalid
			invalid += (s + 1) * (s + 2) / 2
		} else {
			// Sum from t=0 to m of (t+1) = (m+1)*(m+2)/2
			invalid += (m + 1) * (m + 2) / 2
