func countInvalid(x, sumOther, l int) int {
	count := 0
	// The maximum possible increase for x is l
	// For x + dx to be >= sumOther + dy + dz, we need dx >= sumOther - x + dy + dz
	// Since dy + dz <= l - dx, we have dx >= sumOther - x + (l - dx)
