	// For dx from minDx to l:
	//   k = min(l - dx, x + dx - sumOther)
	//   We need to find when l - dx <= x + dx - sumOther
	//   l - dx <= x + dx - sumOther
	//   l + sumOther - x <= 2dx
	//   dx >= (l + sumOther - x) / 2
	// Let threshold = (l + sumOther - x + 1) / 2 (ceiling division)
	// For dx from minDx to threshold-1: k = x + dx - sumOther
	// For dx from threshold to l: k = l - dx

	// Calculate the first part: dx from minDx to threshold-1
	minDx := sumOther - x
	if minDx < 0 {
		minDx = 0
	}
	if minDx > l {
		return 0
	}

	threshold := (l + sumOther - x + 1) / 2
	if threshold < minDx {
		threshold = minDx
	}

	// First part: dx from minDx to min(threshold-1, l)
	endFirst := threshold - 1
	if endFirst > l {
		endFirst = l
	}
	if endFirst < minDx {
		endFirst = minDx - 1
	}

	// Sum for first part: sum_{dx=minDx}^{endFirst} (x + dx - sumOther + 1)(x + dx - sumOther + 2)/2
	// Let t = dx - minDx, then dx = minDx + t
	// x + dx - sumOther = x + minDx + t - sumOther = (x + sumOther - x) + t - sumOther = sumOther + t - sumOther = t
	// Wait, minDx = sumOther - x, so x + minDx - sumOther = x + sumOther - x - sumOther = 0
	// So x + dx - sumOther = dx - minDx = t
	// So the sum becomes sum_{t=0}^{endFirst - minDx} (t+1)(t+2)/2
	// This is sum_{t=0}^{n} (t+1)(t+2)/2 where n = endFirst - minDx
	// (t+1)(t+2)/2 = C(t+2, 2)
	// sum_{t=0}^{n} C(t+2, 2) = C(n+3, 3) = (n+3)(n+2)(n+1)/6
	n1 := endFirst - minDx
	if n1 >= 0 {
		count += (n1 + 3) * (n1 + 2) * (n1 + 1) / 6
	}

	// Second part: dx from threshold to l
	// k = l - dx
	// Sum_{dx=threshold}^{l} (l - dx + 1)(l - dx + 2)/2
	// Let t = l - dx, then dx = l - t
	// When dx = threshold, t = l - threshold
	// When dx = l, t = 0
	// So sum_{t=0}^{l - threshold} (t+1)(t+2)/2 = C(l - threshold + 3, 3)
	n2 := l - threshold
	if n2 >= 0 {
		count += (n2 + 3) * (n2 + 2) * (n2 + 1) / 6
	}

	return count
}
