package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var a, b, c, l int
	fmt.Fscan(reader, &a, &b, &c, &l)

	// Sort the sticks
	arr := []int{a, b, c}
	for i := 0; i < 3; i++ {
		for j := i + 1; j < 3; j++ {
			if arr[i] > arr[j] {
				arr[i], arr[j] = arr[j], arr[i]
			}
		}
	}
	x, y, z := arr[0], arr[1], arr[2]

	// Total number of ways to distribute up to l increases
	total := (l + 1) * (l + 2) * (l + 3) / 6

	// Calculate the number of invalid ways
	invalid := 0
	// For each possible increase in z (the largest stick)
	for dz := 0; dz <= l; dz++ {
		// The remaining increases for x and y
		rem := l - dz
		// The maximum increase for x and y such that x + dx + y + dy <= z + dz
		// i.e., dx + dy <= (z + dz) - (x + y)
		// If (z + dz) - (x + y) < 0, then all distributions are invalid
		threshold := (z + dz) - (x + y)
		if threshold < 0 {
			// All distributions of rem increases to x and y are invalid
			invalid += (rem + 1) * (rem + 2) / 2
		} else {
			// Number of (dx, dy) pairs where dx + dy > threshold and dx + dy <= rem
			// This is equivalent to sum_{s=threshold+1}^{rem} (s + 1)
			// Which is sum_{s=0}^{rem} (s + 1) - sum_{s=0}^{threshold} (s + 1)
			// = (rem + 1)(rem + 2)/2 - (threshold + 1)(threshold + 2)/2
			if rem >= threshold+1 {
				invalid += (rem + 1) * (rem + 2) / 2 - (threshold + 1) * (threshold + 2) / 2
			}
		}
	}

	result := total - invalid
	if result < 0 {
		result = 0
	}
	fmt.Println(result)
}
