package main

import (
	"fmt"
)

func main() {
	var a, b, c, l int
	fmt.Scan(&a, &b, &c, &l)

	// Sort the sticks so that a <= b <= c
	if a > b {
		a, b = b, a
	}
	if b > c {
		b, c = c, b
	}
	if a > b {
		a, b = b, a
	}

	total := 0
	for x := 0; x <= l; x++ {
		for y := 0; y <= l-x; y++ {
			z := l - x - y
			// z is the remaining after x and y; but we need to consider all possible z up to l-x-y
			// Actually, we need to iterate over all possible z such that x+y+z <= l
			// So we should iterate z from 0 to l-x-y
			for zz := 0; zz <= z; zz++ {
				na := a + x
				nb := b + y
				nc := c + zz
				if na+nb > nc && na+nc > nb && nb+nc > na {
					total++
				}
			}
		}
	}
	fmt.Println(total)
}
